fun setPreviewParameters(
    livePreview: LivePreview,
    iso: Int,
    exposureTimeNs: Long,
    dynamicBlackLevel: FloatArray?,
    awbGains: FloatArray?,
    colorMatrix: FloatArray?,
    autoLevelsMode: Int,
    showHistogram: Boolean,
    logRange: Float,
    useSpatialDenoise: Boolean,
    useFalseColor: Boolean,
    highlightRecoveryEnabled: Boolean
) {
    livePreview.setIso(iso)
    livePreview.setExposureTime(exposureTimeNs)
    livePreview.setBlackLevelPattern(dynamicBlackLevel ?: floatArrayOf(64f, 64f, 64f, 64f))
    if (awbGains != null) {
        livePreview.setWbGains(
            maxOf(0.1f, awbGains[0]),
            maxOf(0.1f, awbGains[1]),
            maxOf(0.1f, awbGains[2])
        )
    }
    if (colorMatrix != null) {
        livePreview.setColorMatrix(colorMatrix)
    }
    livePreview.setAutoLevelsMode(autoLevelsMode)
    livePreview.setShowHistogram(showHistogram)
    livePreview.setLogRange(logRange)
    livePreview.setPipelineSettings(
        useSpatialDenoise, useFalseColor, highlightRecoveryEnabled
    )
}

fun Context.findActivity(): androidx.activity.ComponentActivity? = when (this) {
    is androidx.activity.ComponentActivity -> this
    is android.content.ContextWrapper -> baseContext.findActivity()
    else -> null
}
fun formatShutterSpeed(exposureTimeNs: Long): String {
    val seconds = exposureTimeNs / 1_000_000_000.toFloat()
    if (seconds >= 1f) {
        val whole = seconds.toInt()
        val remainder = exposureTimeNs - whole * 1_000_000_000L
        if (remainder == 0L) {
            return "$whole s"
        } else {
            return "$whole.${remainder / 1_000_000}f s"
        }
    } else if (seconds >= 0.5f) {
        val tenth = (seconds * 10f).toInt() / 10f
        return "$tenth s"
    } else {
        val denominator = kotlin.math.roundToLong(1_000_000_000.0 / exposureTimeNs.toDouble()).toLong()
        when {
            denominator in 30..1000 -> "1/$denominator s"
            else -> "${exposureTimeNs / 1_000_000_000.toFloat()} s"
        }
    }
}

